import { useEffect, useMemo, useState } from "react";
import { getChildren } from "../api/api";

const classNames = ["Blueberry", "Rose Berry", "BlackBerry"];

function ClassManagement() {
  const [children, setChildren] = useState([]);
  const [activeClass, setActiveClass] = useState(classNames[0]);

  useEffect(() => {
    getChildren().then(res => setChildren(res)).catch(err => console.log(err));
  }, []);

  const grouped = useMemo(() => {
    return classNames.map(name => ({
      name,
      children: children.filter(child => child.class === name)
    }));
  }, [children]);

  const activeGroup = grouped.find(group => group.name === activeClass) || grouped[0];

  return (
    <div>
      <h2>Class Management</h2>
      <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", marginBottom: "20px" }}>
        {grouped.map(group => (
          <button
            key={group.name}
            onClick={() => setActiveClass(group.name)}
            style={{
              padding: "10px 16px",
              borderRadius: "999px",
              border: activeClass === group.name ? "2px solid #222" : "1px solid #ccc",
              background: activeClass === group.name ? "#e8f0ff" : "white",
              cursor: "pointer"
            }}
          >
            {group.name} ({group.children.length})
          </button>
        ))}
      </div>

      <div style={{ maxWidth: "640px" }}>
        <h3>{activeGroup.name}</h3>
        {activeGroup.children.length === 0 ? (
          <p>No children assigned to this class yet.</p>
        ) : (
          <ul>
            {activeGroup.children.map(child => (
              <li key={child.id}>{child.name} — Age {child.age}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default ClassManagement;
